use runar::prelude::*;

#[runar::contract]
pub struct TxPre {
    pub tx_preimage: SigHashPreimage,
}

impl TxPre {
    pub fn spend(&self, x: Bigint) {
        assert!(extract_amount(&self.tx_preimage) >= x);
    }
}

use runar::prelude::*;

#[runar::contract]
pub struct TxPreRo {
    #[readonly]
    pub min: Bigint,
    pub tx_preimage: SigHashPreimage,
}

impl TxPreRo {
    pub fn spend(&self, x: Bigint) {
        assert!(extract_amount(&self.tx_preimage) >= self.min + x);
    }
}

