use runar::prelude::*;

#[runar::stateful_contract]
pub struct TxPreStateful {
    pub count: Bigint,
    pub tx_preimage: SigHashPreimage,
}

impl TxPreStateful {
    pub fn bump(&mut self, x: Bigint) {
        assert!(extract_amount(&self.tx_preimage) >= x);
        self.count = self.count + 1;
    }
}

